#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    int size = n;
    vector<vector<int>> grid(size, vector<int>(size, 0));
    int top = 0, bottom = size - 1, left = 0, right = size - 1;
    int value = 1;
    while (top <= bottom && left <= right) {
        for (int j = left; j <= right; j++) {
            grid[top][j] = value++;
        }
        top++;
        for (int i = top; i <= bottom; i++) {
            grid[i][right] = value++;
        }
        right--;
        if (top <= bottom) {
            for (int j = right; j >= left; j--) {
                grid[bottom][j] = value++;
            }
            bottom--;
        }
        if (left <= right) {
            for (int i = bottom; i >= top; i--) {
                grid[i][left] = value++;
            }
            left++;
        }
    }
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            cout << grid[i][j] << " ";
        }
        cout << endl;
    }

    return 0;
}

